"""Persistent, thread-safe job registry."""

from __future__ import annotations

import contextlib
import json
import os
import tempfile
import threading
from typing import Any

from ._jsonio import strict_loads

__all__ = ["register"]

_VERSION = 1
_STATE = "queued"
_JOB_FIELDS = ("job_id", "deadline", "energy_wh", "residency_regions", "state")
_REQUIRED_FIELDS = frozenset(_JOB_FIELDS[:-1])
_ROOT_FIELDS = ("version", "jobs", "idempotency")


class _Store:
    def __init__(self, realpath: str) -> None:
        self.realpath = realpath
        self.lock = threading.Lock()


_stores_lock = threading.Lock()
_stores: dict[str, _Store] = {}


def _get_store(path: str) -> _Store:
    realpath = os.path.realpath(path)
    with _stores_lock:
        store = _stores.get(realpath)
        if store is None:
            store = _Store(realpath)
            _stores[realpath] = store
        return store


def _is_plain_int(value: object) -> bool:
    # bool is a subclass of int and must be rejected.
    return isinstance(value, int) and not isinstance(value, bool)


def _normalize_job(job: object) -> tuple[str, int, int, list[str]]:
    if not isinstance(job, dict) or set(job.keys()) != _REQUIRED_FIELDS:
        raise ValueError("job must be an object with exactly job_id, deadline, "
                         "energy_wh and residency_regions")

    job_id = job["job_id"]
    if not isinstance(job_id, str) or not job_id:
        raise ValueError("job_id must be a non-empty string")

    deadline = job["deadline"]
    if not _is_plain_int(deadline) or deadline < 0:
        raise ValueError("deadline must be a non-boolean non-negative integer")

    energy_wh = job["energy_wh"]
    if not _is_plain_int(energy_wh) or energy_wh <= 0:
        raise ValueError("energy_wh must be a non-boolean positive integer")

    regions = job["residency_regions"]
    if not isinstance(regions, list) or not regions:
        raise ValueError("residency_regions must be a non-empty list")
    normalized: list[str] = []
    seen: set[str] = set()
    for region in regions:
        if not isinstance(region, str) or not region:
            raise ValueError("residency regions must be non-empty strings")
        if region in seen:
            raise ValueError("residency regions must be distinct")
        seen.add(region)
        normalized.append(region)
    normalized.sort()  # Python str ordering is Unicode code-point ordering.

    return job_id, deadline, energy_wh, normalized


def _validate_regions(regions: object) -> list[str]:
    if not isinstance(regions, list) or not regions:
        raise ValueError("residency_regions must be a non-empty list")
    seen: set[str] = set()
    for region in regions:
        if not isinstance(region, str) or not region or region in seen:
            raise ValueError("invalid residency region")
        seen.add(region)
    if regions != sorted(regions):
        raise ValueError("residency_regions are not normalized")
    return list(regions)


def _validate_structure(
    data: object,
) -> tuple[dict[str, dict[str, Any]], dict[str, str]]:
    if not isinstance(data, dict) or set(data.keys()) != set(_ROOT_FIELDS):
        raise ValueError("registry root must be an object with keys "
                         "version, jobs and idempotency")

    version = data["version"]
    if not _is_plain_int(version) or version != _VERSION:
        raise ValueError("unsupported registry version")

    jobs_raw = data["jobs"]
    idempotency_raw = data["idempotency"]
    if not isinstance(jobs_raw, dict) or not isinstance(idempotency_raw, dict):
        raise ValueError("jobs and idempotency must be objects")

    jobs: dict[str, dict[str, Any]] = {}
    for name, record in jobs_raw.items():
        if not isinstance(name, str) or not name:
            raise ValueError("job ids must be non-empty strings")
        if not isinstance(record, dict) or set(record.keys()) != set(_JOB_FIELDS):
            raise ValueError("job record has invalid fields")
        if record["job_id"] != name:
            raise ValueError("job record id does not match its key")
        if not isinstance(record["job_id"], str):
            raise ValueError("job_id must be a string")
        if not _is_plain_int(record["deadline"]) or record["deadline"] < 0:
            raise ValueError("invalid deadline")
        if not _is_plain_int(record["energy_wh"]) or record["energy_wh"] <= 0:
            raise ValueError("invalid energy_wh")
        _validate_regions(record["residency_regions"])
        if record["state"] != _STATE:
            raise ValueError("invalid job state")
        jobs[name] = dict(record)

    idempotency: dict[str, str] = {}
    referenced: set[str] = set()
    for key, job_id in idempotency_raw.items():
        if not isinstance(key, str) or not key:
            raise ValueError("idempotency keys must be non-empty strings")
        if not isinstance(job_id, str) or not job_id or job_id not in jobs:
            raise ValueError("idempotency entry must reference a registered job")
        if job_id in referenced:
            raise ValueError("job registered under more than one idempotency key")
        referenced.add(job_id)
        idempotency[key] = job_id

    return jobs, idempotency


def _load(realpath: str) -> tuple[dict[str, dict[str, Any]], dict[str, str]]:
    try:
        with open(realpath, encoding="utf-8") as handle:
            text = handle.read()
    except FileNotFoundError:
        return {}, {}

    try:
        data = strict_loads(text)
    except ValueError as exc:
        raise ValueError(f"registry file {realpath!r} is not valid JSON") from exc
    return _validate_structure(data)


def _atomic_write(
    realpath: str,
    jobs: dict[str, dict[str, Any]],
    idempotency: dict[str, str],
) -> None:
    payload = {
        "version": _VERSION,
        "jobs": {name: jobs[name] for name in sorted(jobs)},
        "idempotency": {key: idempotency[key] for key in sorted(idempotency)},
    }
    text = json.dumps(payload, ensure_ascii=False, separators=(",", ":"),
                      allow_nan=False) + "\n"

    directory = os.path.dirname(realpath) or "."
    fd, tmp_path = tempfile.mkstemp(dir=directory, prefix=".jobs-", suffix=".tmp")
    try:
        with os.fdopen(fd, "w", encoding="utf-8", newline="") as handle:
            handle.write(text)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(tmp_path, realpath)
    except BaseException:
        with contextlib.suppress(OSError):
            os.unlink(tmp_path)
        raise

    with contextlib.suppress(OSError):
        dir_fd = os.open(directory, os.O_RDONLY)
        try:
            os.fsync(dir_fd)
        finally:
            os.close(dir_fd)


def register(
    path: str,
    job: dict[str, object],
    idempotency_key: str,
) -> tuple[dict[str, object], bool]:
    """Register a job idempotently, persisting it as compact UTF-8 JSON.

    Returns ``(record, created)`` where ``record`` carries job_id, deadline,
    energy_wh, residency_regions (sorted by code point) and ``state`` set to
    ``"queued"``; ``created`` is ``True`` for a new registration and ``False``
    when the idempotency key replays an identical, normalized job.
    """
    if not isinstance(path, str):
        raise ValueError("path must be a string")
    if not isinstance(idempotency_key, str) or not idempotency_key:
        raise ValueError("idempotency_key must be a non-empty string")
    job_id, deadline, energy_wh, regions = _normalize_job(job)

    store = _get_store(path)
    with store.lock:
        jobs, idempotency = _load(store.realpath)
        record: dict[str, object] = {
            "job_id": job_id,
            "deadline": deadline,
            "energy_wh": energy_wh,
            "residency_regions": regions,
            "state": _STATE,
        }

        existing_id = idempotency.get(idempotency_key)
        if existing_id is not None:
            existing = jobs[existing_id]
            if existing != record:
                raise ValueError("idempotency key was already used with a "
                                 "different job")
            return dict(existing), False

        if job_id in jobs:
            raise ValueError("job_id is already registered under another "
                             "idempotency key")

        jobs[job_id] = record
        idempotency[idempotency_key] = job_id
        _atomic_write(store.realpath, jobs, idempotency)
        return dict(record), True

"""Persistent, thread-safe capacity-offer registry."""

from __future__ import annotations

import contextlib
import json
import os
import tempfile
import threading
from typing import Any

from ._jsonio import strict_loads

__all__ = ["register"]

_VERSION = 1
_OFFER_FIELDS = ("resource_id", "region", "capacity_wh",
                 "unit_cost", "carbon_intensity")
_REQUIRED_FIELDS = frozenset(_OFFER_FIELDS)
_ROOT_FIELDS = ("version", "offers", "idempotency")


class _Store:
    def __init__(self, realpath: str) -> None:
        self.realpath = realpath
        self.lock = threading.Lock()


_stores_lock = threading.Lock()
_stores: dict[str, _Store] = {}


def _get_store(path: str) -> _Store:
    realpath = os.path.realpath(path)
    with _stores_lock:
        store = _stores.get(realpath)
        if store is None:
            store = _Store(realpath)
            _stores[realpath] = store
        return store


def _is_plain_int(value: object) -> bool:
    # bool is a subclass of int and must be rejected.
    return isinstance(value, int) and not isinstance(value, bool)


def _normalize_offer(
    offer: object,
) -> tuple[str, str, int, int, int]:
    if not isinstance(offer, dict) or set(offer.keys()) != _REQUIRED_FIELDS:
        raise ValueError("offer must be an object with exactly resource_id, "
                         "region, capacity_wh, unit_cost and carbon_intensity")

    resource_id = offer["resource_id"]
    if not isinstance(resource_id, str) or not resource_id:
        raise ValueError("resource_id must be a non-empty string")

    region = offer["region"]
    if not isinstance(region, str) or not region:
        raise ValueError("region must be a non-empty string")

    capacity_wh = offer["capacity_wh"]
    if not _is_plain_int(capacity_wh) or capacity_wh <= 0:
        raise ValueError("capacity_wh must be a non-boolean positive integer")

    unit_cost = offer["unit_cost"]
    if not _is_plain_int(unit_cost) or unit_cost < 0:
        raise ValueError("unit_cost must be a non-boolean non-negative integer")

    carbon_intensity = offer["carbon_intensity"]
    if not _is_plain_int(carbon_intensity) or carbon_intensity < 0:
        raise ValueError("carbon_intensity must be a non-boolean "
                         "non-negative integer")

    return resource_id, region, capacity_wh, unit_cost, carbon_intensity


def _validate_structure(
    data: object,
) -> tuple[dict[str, dict[str, Any]], dict[str, dict[str, str]]]:
    if not isinstance(data, dict) or set(data.keys()) != set(_ROOT_FIELDS):
        raise ValueError("registry root must be an object with keys "
                         "version, offers and idempotency")

    version = data["version"]
    if not _is_plain_int(version) or version != _VERSION:
        raise ValueError("unsupported registry version")

    offers_raw = data["offers"]
    idempotency_raw = data["idempotency"]
    if not isinstance(offers_raw, dict) or not isinstance(idempotency_raw, dict):
        raise ValueError("offers and idempotency must be objects")

    offers: dict[str, dict[str, Any]] = {}
    for name, record in offers_raw.items():
        if not isinstance(name, str) or not name:
            raise ValueError("resource ids must be non-empty strings")
        if not isinstance(record, dict) or set(record.keys()) != _REQUIRED_FIELDS:
            raise ValueError("offer record has invalid fields")
        if record["resource_id"] != name:
            raise ValueError("offer record id does not match its key")
        if not isinstance(record["region"], str) or not record["region"]:
            raise ValueError("region must be a non-empty string")
        if (not _is_plain_int(record["capacity_wh"])
                or record["capacity_wh"] <= 0):
            raise ValueError("invalid capacity_wh")
        if not _is_plain_int(record["unit_cost"]) or record["unit_cost"] < 0:
            raise ValueError("invalid unit_cost")
        if (not _is_plain_int(record["carbon_intensity"])
                or record["carbon_intensity"] < 0):
            raise ValueError("invalid carbon_intensity")
        # Rebuild in canonical field order so that replays and rewrites of
        # records stored out of order still follow _OFFER_FIELDS.
        offers[name] = {field: record[field] for field in _OFFER_FIELDS}

    idempotency: dict[str, dict[str, str]] = {}
    referenced: set[str] = set()
    for key, entry in idempotency_raw.items():
        if not isinstance(key, str) or not key:
            raise ValueError("idempotency keys must be non-empty strings")
        if not isinstance(entry, dict) or set(entry.keys()) != {"resource_id"}:
            raise ValueError("idempotency entry must be a resource_id object")
        resource_id = entry["resource_id"]
        if not isinstance(resource_id, str) or not resource_id \
                or resource_id not in offers:
            raise ValueError("idempotency entry must reference a "
                             "registered offer")
        if resource_id in referenced:
            raise ValueError("offer registered under more than one "
                             "idempotency key")
        referenced.add(resource_id)
        idempotency[key] = {"resource_id": resource_id}

    return offers, idempotency


def _load(
    realpath: str,
) -> tuple[dict[str, dict[str, Any]], dict[str, dict[str, str]]]:
    try:
        with open(realpath, encoding="utf-8") as handle:
            text = handle.read()
    except FileNotFoundError:
        return {}, {}

    try:
        data = strict_loads(text)
    except ValueError as exc:
        raise ValueError(f"registry file {realpath!r} is not valid JSON") from exc
    return _validate_structure(data)


def _atomic_write(
    realpath: str,
    offers: dict[str, dict[str, Any]],
    idempotency: dict[str, dict[str, str]],
) -> None:
    payload = {
        "version": _VERSION,
        "offers": {name: offers[name] for name in sorted(offers)},
        "idempotency": {key: idempotency[key] for key in sorted(idempotency)},
    }
    text = json.dumps(payload, ensure_ascii=False, separators=(",", ":"),
                      allow_nan=False) + "\n"

    directory = os.path.dirname(realpath) or "."
    fd, tmp_path = tempfile.mkstemp(dir=directory, prefix=".offers-",
                                    suffix=".tmp")
    try:
        with os.fdopen(fd, "w", encoding="utf-8", newline="") as handle:
            handle.write(text)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(tmp_path, realpath)
    except BaseException:
        with contextlib.suppress(OSError):
            os.unlink(tmp_path)
        raise

    with contextlib.suppress(OSError):
        dir_fd = os.open(directory, os.O_RDONLY)
        try:
            os.fsync(dir_fd)
        finally:
            os.close(dir_fd)


def register(
    path: str,
    offer: dict[str, object],
    idempotency_key: str,
) -> tuple[dict[str, object], bool]:
    """Register a capacity offer idempotently as compact UTF-8 JSON.

    Returns ``(record, created)`` where ``record`` carries resource_id,
    region, capacity_wh, unit_cost (micro-units per Wh) and carbon_intensity
    (g/kWh); ``created`` is ``True`` for a new registration and ``False``
    when the idempotency key replays an identical offer.
    """
    if not isinstance(path, str):
        raise ValueError("path must be a string")
    if not isinstance(idempotency_key, str) or not idempotency_key:
        raise ValueError("idempotency_key must be a non-empty string")
    resource_id, region, capacity_wh, unit_cost, carbon_intensity = \
        _normalize_offer(offer)

    store = _get_store(path)
    with store.lock:
        offers, idempotency = _load(store.realpath)
        record: dict[str, object] = {
            "resource_id": resource_id,
            "region": region,
            "capacity_wh": capacity_wh,
            "unit_cost": unit_cost,
            "carbon_intensity": carbon_intensity,
        }

        existing_entry = idempotency.get(idempotency_key)
        if existing_entry is not None:
            existing = offers[existing_entry["resource_id"]]
            if existing != record:
                raise ValueError("idempotency key was already used with a "
                                 "different offer")
            return dict(existing), False

        if resource_id in offers:
            raise ValueError("resource_id is already registered under "
                             "another idempotency key")

        offers[resource_id] = record
        idempotency[idempotency_key] = {"resource_id": resource_id}
        _atomic_write(store.realpath, offers, idempotency)
        return dict(record), True

"""Strict JSON decoding shared by the persistent registries.

The only difference from :func:`json.loads` is that number tokens whose
lexical form is a negative zero (``-0``, ``-0.0``, ``-0e2`` ...) are rejected.
``json.loads`` silently normalizes ``-0`` to the integer ``0`` and ``-0.0``
to a non-negative float, which would let two byte-different files compare
equal; the registries instead treat such literals as malformed input. The
hooks only see number tokens, so a ``-0`` appearing inside a string is never
inspected.
"""

from __future__ import annotations

import json

__all__ = ["strict_loads"]


def _is_negative_zero(token: str) -> bool:
    body = token.lstrip()
    if not body.startswith("-"):
        return False
    # A signed numeric token is negative zero exactly when its value is zero;
    # -0.5 stays non-zero, while every spelling of -0 (fraction/exponent) maps
    # to zero.
    return float(body) == 0.0


def _parse_int(token: str) -> int:
    if _is_negative_zero(token):
        raise ValueError("negative-zero number literal is not allowed")
    return int(token)


def _parse_float(token: str) -> float:
    if _is_negative_zero(token):
        raise ValueError("negative-zero number literal is not allowed")
    return float(token)


def strict_loads(text: str) -> object:
    """Parse JSON, raising ValueError on negative-zero number literals."""
    return json.loads(text, parse_int=_parse_int, parse_float=_parse_float)

"""Persistent, thread-safe job-to-offer match ledger."""

from __future__ import annotations

import contextlib
import json
import os
import tempfile
import threading
from typing import Any, Callable

from . import jobs as _jobs
from . import offers as _offers
from ._jsonio import strict_loads

__all__ = ["match"]

_VERSION = 1
_MATCH_FIELDS = ("job_id", "resource_id")
_ROOT_FIELDS = ("version", "matches", "idempotency")


class _Store:
    def __init__(self, realpath: str) -> None:
        self.realpath = realpath
        self.lock = threading.Lock()


_stores_lock = threading.Lock()
_stores: dict[str, _Store] = {}


def _get_store(path: str) -> _Store:
    realpath = os.path.realpath(path)
    with _stores_lock:
        store = _stores.get(realpath)
        if store is None:
            store = _Store(realpath)
            _stores[realpath] = store
        return store


def _is_plain_int(value: object) -> bool:
    # bool is a subclass of int and must be rejected.
    return isinstance(value, int) and not isinstance(value, bool)


def _load_registry(
    realpath: str,
    validate: Callable[[object], tuple[dict[str, dict[str, Any]], Any]],
    kind: str,
) -> tuple[dict[str, dict[str, Any]], Any]:
    # Unlike the registries themselves, match() requires the jobs and offers
    # files to exist, so FileNotFoundError (and any other OSError) propagates.
    with open(realpath, encoding="utf-8") as handle:
        text = handle.read()
    try:
        data = strict_loads(text)
    except ValueError as exc:
        raise ValueError(
            f"{kind} file {realpath!r} is not valid JSON") from exc
    return validate(data)


def _validate_ledger(
    data: object,
    job_ids: dict[str, Any],
    resource_ids: dict[str, Any],
) -> tuple[dict[str, dict[str, str]], dict[str, str]]:
    if not isinstance(data, dict) or set(data.keys()) != set(_ROOT_FIELDS):
        raise ValueError("ledger root must be an object with keys "
                         "version, matches and idempotency")

    version = data["version"]
    if not _is_plain_int(version) or version != _VERSION:
        raise ValueError("unsupported ledger version")

    matches_raw = data["matches"]
    idempotency_raw = data["idempotency"]
    if not isinstance(matches_raw, dict) or not isinstance(idempotency_raw, dict):
        raise ValueError("matches and idempotency must be objects")

    matches: dict[str, dict[str, str]] = {}
    for name, record in matches_raw.items():
        if not isinstance(name, str) or not name:
            raise ValueError("job ids must be non-empty strings")
        if not isinstance(record, dict) or set(record.keys()) != set(_MATCH_FIELDS):
            raise ValueError("match record has invalid fields")
        if record["job_id"] != name:
            raise ValueError("match record id does not match its key")
        resource_id = record["resource_id"]
        if not isinstance(resource_id, str) or not resource_id:
            raise ValueError("resource_id must be a non-empty string")
        if name not in job_ids:
            raise ValueError("match record must reference a registered job")
        if resource_id not in resource_ids:
            raise ValueError("match record must reference a registered offer")
        matches[name] = {"job_id": name, "resource_id": resource_id}

    idempotency: dict[str, str] = {}
    referenced: set[str] = set()
    for key, job_id in idempotency_raw.items():
        if not isinstance(key, str) or not key:
            raise ValueError("idempotency keys must be non-empty strings")
        if not isinstance(job_id, str) or not job_id or job_id not in matches:
            raise ValueError("idempotency entry must reference a recorded match")
        if job_id in referenced:
            raise ValueError("job matched under more than one idempotency key")
        referenced.add(job_id)
        idempotency[key] = job_id

    return matches, idempotency


def _load_ledger(
    realpath: str,
    job_ids: dict[str, Any],
    resource_ids: dict[str, Any],
) -> tuple[dict[str, dict[str, str]], dict[str, str]]:
    try:
        with open(realpath, encoding="utf-8") as handle:
            text = handle.read()
    except FileNotFoundError:
        return {}, {}

    try:
        data = strict_loads(text)
    except ValueError as exc:
        raise ValueError(f"ledger file {realpath!r} is not valid JSON") from exc
    return _validate_ledger(data, job_ids, resource_ids)


def _atomic_write(
    realpath: str,
    matches: dict[str, dict[str, str]],
    idempotency: dict[str, str],
) -> None:
    payload = {
        "version": _VERSION,
        "matches": {name: matches[name] for name in sorted(matches)},
        "idempotency": {key: idempotency[key] for key in sorted(idempotency)},
    }
    text = json.dumps(payload, ensure_ascii=False, separators=(",", ":"),
                      allow_nan=False) + "\n"

    directory = os.path.dirname(realpath) or "."
    fd, tmp_path = tempfile.mkstemp(dir=directory, prefix=".ledger-",
                                    suffix=".tmp")
    try:
        with os.fdopen(fd, "w", encoding="utf-8", newline="") as handle:
            handle.write(text)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(tmp_path, realpath)
    except BaseException:
        with contextlib.suppress(OSError):
            os.unlink(tmp_path)
        raise

    with contextlib.suppress(OSError):
        dir_fd = os.open(directory, os.O_RDONLY)
        try:
            os.fsync(dir_fd)
        finally:
            os.close(dir_fd)


def match(
    jobs: str,
    offers: str,
    ledger: str,
    job_id: str,
    key: str,
) -> tuple[dict[str, object], bool]:
    """Match a registered job to the greenest feasible offer idempotently.

    Candidates are offers whose region is permitted by the job's
    residency_regions and whose remaining capacity (capacity_wh minus the
    energy already allocated in the ledger) covers the job's energy_wh;
    the winner is the first by ascending carbon_intensity, unit_cost and
    resource_id. Returns ``(record, created)`` where ``record`` carries
    job_id and resource_id; ``created`` is ``True`` for a new match and
    ``False`` when the idempotency key replays a match for the same job
    (which allocates no further capacity).
    """
    for value in (jobs, offers, ledger, job_id, key):
        if not isinstance(value, str) or not value:
            raise ValueError("jobs, offers, ledger, job_id and key must be "
                             "non-empty strings")

    store = _get_store(ledger)
    with store.lock:
        job_records, _ = _load_registry(
            os.path.realpath(jobs), _jobs._validate_structure, "jobs registry")
        if job_id not in job_records:
            raise KeyError(job_id)
        job = job_records[job_id]

        offer_records, _ = _load_registry(
            os.path.realpath(offers), _offers._validate_structure,
            "offers registry")
        matches, idempotency = _load_ledger(
            store.realpath, job_records, offer_records)

        existing = idempotency.get(key)
        if existing is not None:
            if existing != job_id:
                raise ValueError("idempotency key was already used with a "
                                 "different job")
            return dict(matches[job_id]), False
        if job_id in matches:
            raise ValueError("job is already matched under another "
